const otDenverSections=[
 ['problem','Sebab saringan','Reason for screening','Kebimbangan penjaga, sebab rujukan dan tujuan saringan.'],
 ['background','Latar belakang perkembangan','Developmental background','Sejarah perkembangan, perubatan, kelahiran dan konteks keluarga yang berkaitan.'],
 ['personalSocial','Personal-social','Personal-social','Catat dapatan domain berdasarkan pentadbiran borang rasmi. Jika tidak dinilai, nyatakan sebab.'],
 ['fineMotor','Motor halus-adaptif','Fine motor-adaptive','Catat dapatan domain berdasarkan pentadbiran borang rasmi. Jika tidak dinilai, nyatakan sebab.'],
 ['language','Bahasa','Language','Catat dapatan domain berdasarkan pentadbiran borang rasmi. Jika tidak dinilai, nyatakan sebab.'],
 ['grossMotor','Motor kasar','Gross motor','Catat dapatan domain berdasarkan pentadbiran borang rasmi. Jika tidak dinilai, nyatakan sebab.'],
 ['behavior','Pemerhatian semasa saringan','Screening observations','Kerjasama, perhatian, keadaan sesi dan faktor yang mungkin mempengaruhi kebolehpercayaan dapatan.'],
 ['impression','Rumusan saringan','Screening summary','Catat tafsiran terapis berdasarkan borang dan manual rasmi. Saringan bukan diagnosis.'],
 ['recommendations','Cadangan & susulan','Recommendations and follow-up','Rancangan susulan, penilaian lanjut, rujukan atau panduan penjaga mengikut pertimbangan terapis.']
];
const otDenverDomains=['personalSocial','fineMotor','language','grossMotor'];
const isDenverAssessment=a=>a?.type==='ot-denver';
const isOtAssessment=a=>isDenverAssessment(a)||isSspAssessment(a);
const assessmentSectionsFor=a=>isSspAssessment(a)?sspSections:isDenverAssessment(a)?otDenverSections:assessmentSections;
const assessmentRole=a=>isOtAssessment(a)?'Occupational Therapist':'Speech Therapist';
const assessmentTypeLabel=a=>isSspAssessment(a)?'OT · Short Sensory Profile':isDenverAssessment(a)?'OT · Rekod Denver II':'Pertuturan & bahasa';
function chooseAssessmentType(){if(assessmentDirty){notify('Simpan draf semasa sebelum membuka assessment lain.');return}open('Pilih jenis assessment',`<div class="assessment-type-options"><button class="secondary" type="button" data-assessment-type="speech"><b>Pertuturan & bahasa</b><span>Borang assessment Speech Therapist</span></button><button class="secondary" type="button" data-assessment-type="ot-denver"><b>Occupational Therapy · Denver II</b><span>Rekod saringan menggunakan borang/manual rasmi</span></button><button class="secondary" type="button" data-assessment-type="ot-ssp"><b>Occupational Therapy · Short Sensory Profile</b><span>SSP asal (1999) · Rekod soal selidik penjaga</span></button></div>`)}
function denverAgeNotice(a){if(!a.dob||!a.date)return 'Julat rujukan Denver II: 0–6 tahun. Semak kelayakan umur menggunakan manual rasmi.';const end=new Date(a.dob+'T00:00:00Z');end.setUTCFullYear(end.getUTCFullYear()+6);return new Date(a.date+'T00:00:00Z')>end?'Umur kronologi melebihi 6 tahun. Denver II di luar julat umur rujukan; rekod ini boleh disimpan sebagai draf.':'Umur kronologi dalam julat rujukan. Semak pelarasan umur, jika berkenaan, menggunakan manual rasmi.'}
function denverAdditionalFields(a){return `<fieldset><legend>02 · Maklumat pentadbiran Denver II</legend><p class="field-hint">Borang ini merekod hasil saringan. Gunakan item, carta umur dan peraturan pemarkahan pada borang/manual Denver II rasmi. Tiada keputusan automatik.</p><p id="denver-age-notice" role="status">${esc(denverAgeNotice(a))}</p><div class="assessment-fields">${assessmentInput('instrumentReference','Versi / bahasa borang dan manual rasmi',a.instrumentReference)}${assessmentInput('formReference','Rujukan rekod borang asal',a.formReference)}${assessmentInput('screeningLanguage','Bahasa pentadbiran / jurubahasa',a.screeningLanguage)}${assessmentInput('ageUsed','Umur yang digunakan pada carta rasmi (diisi terapis)',a.ageUsed)}${assessmentInput('ageBasis','Asas umur / pelarasan prematuriti, jika berkenaan',a.ageBasis)}</div><p class="field-hint">Umur kronologi dalam borang ini bukan garis umur Denver II. Terapis menentukan umur saringan dan sebarang pelarasan mengikut manual.</p></fieldset>`}
function denverItemField(a,key){return `<label class="field" for="assessment-${key}-items">Rujukan item & keputusan daripada borang rasmi (pilihan)</label><textarea id="assessment-${key}-items" name="${key}Items" rows="3" maxlength="6000" placeholder="Catat kod / rujukan item, keputusan yang direkod dan pemerhatian berkaitan.">${esc(a[key+'Items']||'')}</textarea>`}
function denverResultFields(a){return `<fieldset><legend>12 · Keputusan terapis & susulan</legend><div class="assessment-fields">${assessmentInput('screeningResult','Keputusan saringan daripada borang rasmi',a.screeningResult)}${assessmentInput('followUpDate','Tarikh susulan (pilihan)',a.followUpDate,'date')}</div><label class="assessment-confirm"><input type="checkbox" name="officialReviewed" ${a.officialReviewed?'checked':''}> Saya menggunakan borang/manual Denver II rasmi dan telah menyemak pentadbiran serta tafsiran keputusan.</label><p class="field-hint">Keputusan ditaip oleh terapis. Sistem tidak mengira skor, kategori saringan atau diagnosis. <a href="https://www.hogrefe.com/uk/shop/tests/child-development/denver-ii-developmental-screening-test.html" target="_blank" rel="noopener noreferrer">Rujukan instrumen Denver II</a></p></fieldset>`}
function validateDenver(a){for(const [key,label] of [['instrumentReference','versi / bahasa borang dan manual'],['formReference','rujukan borang asal'],['ageUsed','umur yang digunakan pada carta rasmi'],['ageBasis','asas umur atau pelarasan'],['screeningResult','keputusan saringan']])if(!a[key]?.trim())return `Sila isi ${label}.`;const end=new Date(a.dob+'T00:00:00Z');end.setUTCFullYear(end.getUTCFullYear()+6);if(new Date(a.date+'T00:00:00Z')>end)return 'Denver II di luar julat umur rujukan 0–6 tahun. Simpan sebagai draf dan semak instrumen yang sesuai.';if(!a.officialReviewed)return 'Sila sahkan penggunaan dan semakan borang/manual Denver II rasmi.';if(a.followUpDate&&a.followUpDate<a.date)return 'Tarikh susulan tidak boleh sebelum tarikh assessment.';return ''}
function denverReportMetadata(a){return `<section><h4>Maklumat saringan Denver II</h4><p>Rekod saringan bersama borang/manual rasmi; bukan salinan instrumen atau diagnosis.</p><dl>${[['Versi / bahasa manual',a.instrumentReference],['Rujukan borang asal',a.formReference],['Bahasa pentadbiran',a.screeningLanguage],['Umur digunakan pada carta',a.ageUsed],['Asas umur / pelarasan',a.ageBasis],['Keputusan terapis',a.screeningResult],['Tarikh susulan',a.followUpDate]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Belum diisi')}</dd></div>`).join('')}</dl></section>`}
